===== README.md =====
     1	# Skyline Ace
     2	
     3	A standalone React Three Fiber rail-shooter vertical slice. It is an original,
     4	asset-free homage to the *Star Fox 64* design vocabulary: fixed-rail movement,
     5	wingmate rescues, barrel rolls, route landmarks, score chasing, and a staged
     6	carrier boss. It intentionally does **not** ship Nintendo names, dialogue,
     7	sounds, models, textures, level geometry, or ripped game data.
     8	
     9	## Run
    10	
    11	```sh
    12	cd games/skyline-ace
    13	npm install
    14	npm run dev
    15	```
    16	
    17	Controls: `WASD`/arrow keys move, `Space` fires, `Shift` boosts, `E` barrels
    18	roll, and `Q` drops a bomb. A/D or Left/Right double-tap also triggers the roll.
    19	
    20	## Difficulty and targeting model
    21	
    22	`src/game/difficulty.ts` is the single deterministic model. It normalizes route
    23	progress to `distance / 420m` and clamps it to 0..1. Health rises to 1.9x,
    24	fire intervals fall to 0.55x, projectile speed rises to 1.5x, aim lead rises
    25	from 0.15x to 1x, accuracy rises from 34% to 94%, wave density rises to 1.5x,
    26	and formation width rises to 1.22x. Extra formation members are deterministic,
    27	never random. Enemy fire solves a bounded intercept using player position and
    28	velocity, clamps prediction to the playable envelope, and applies a shrinking
    29	seeded offset as accuracy improves. The HUD exposes threat progress, aim
    30	accuracy, and wave density for playtesting.
    31	
    32	## Research notes
    33	
    34	The first *Star Fox 64* stage, Corneria, is a forward-scrolling Arwing mission
    35	with a coastal/city assault, three wingmates, rescue encounters, an optional
    36	landmark route, score/medal replay incentives, and the Attack Carrier boss.
    37	Those high-level, mechanically useful facts informed the encounter script.
    38	Exact counts, timings, and route triggers should be verified from a licensed
    39	copy and original footage before building any production-accurate campaign.
    40	
    41	Reference reading:
    42	
    43	- [StrategyWiki — Star Fox 64 / Corneria](https://strategywiki.org/wiki/Star_Fox_64/Corneria)
    44	- [Star Fox Wiki — Corneria](https://starfox.fandom.com/wiki/Corneria)
    45	- [Star Fox Wiki — Attack Carrier](https://starfox.fandom.com/wiki/Attack_Carrier)
    46	- [Star Fox 64 instruction manual archive](https://www.gamesdatabase.org/Media/SYSTEM/Nintendo_N64/Manual/formated/Star_Fox_64_-_1997_-_Nintendo.pdf)
===== package.json =====
     1	{
     2	  "name": "skyline-ace-r3f",
     3	  "version": "0.1.0",
     4	  "private": true,
     5	  "type": "module",
     6	  "scripts": {
     7	    "dev": "vite",
     8	    "build": "tsc --noEmit && vite build",
     9	    "preview": "vite preview"
    10	  },
    11	  "dependencies": {
    12	    "@react-three/fiber": "^9.1.2",
    13	    "@react-three/postprocessing": "^3.0.4",
    14	    "postprocessing": "^6.37.8",
    15	    "react": "^19.1.0",
    16	    "react-dom": "^19.1.0",
    17	    "three": "^0.177.0"
    18	  },
    19	  "devDependencies": {
    20	    "@types/react": "^19.1.8",
    21	    "@types/react-dom": "^19.1.6",
    22	    "@types/three": "^0.177.0",
    23	    "@vitejs/plugin-react": "^4.4.1",
    24	    "typescript": "^5.8.3",
    25	    "vite": "^6.3.5"
    26	  }
    27	}
===== tsconfig.json =====
     1	{
     2	  "compilerOptions": {
     3	    "target": "ES2022",
     4	    "useDefineForClassFields": true,
     5	    "lib": ["DOM", "DOM.Iterable", "ES2022"],
     6	    "allowJs": false,
     7	    "skipLibCheck": true,
     8	    "esModuleInterop": true,
     9	    "allowSyntheticDefaultImports": true,
    10	    "strict": true,
    11	    "forceConsistentCasingInFileNames": true,
    12	    "module": "ESNext",
    13	    "moduleResolution": "Bundler",
    14	    "resolveJsonModule": true,
    15	    "isolatedModules": true,
    16	    "noEmit": true,
    17	    "jsx": "react-jsx"
    18	  },
    19	  "include": ["src", "vite.config.ts"]
    20	}
===== vite.config.ts =====
     1	import { defineConfig } from 'vite'
     2	import react from '@vitejs/plugin-react'
     3	
     4	export default defineConfig({
     5	  plugins: [react()],
     6	  base: './',
     7	  build: {
     8	    outDir: 'dist',
     9	    emptyOutDir: true,
    10	  },
    11	})
===== index.html =====
     1	<!doctype html>
     2	<html lang="en">
     3	  <head>
     4	    <meta charset="UTF-8" />
     5	    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     6	    <meta name="theme-color" content="#061326" />
     7	    <title>Skyline Ace — rail shooter prototype</title>
     8	  </head>
     9	  <body>
    10	    <div id="root"></div>
    11	    <script type="module" src="/src/main.tsx"></script>
    12	  </body>
    13	</html>
===== src/main.tsx =====
     1	import { StrictMode } from 'react'
     2	import { createRoot } from 'react-dom/client'
     3	import { Game } from './game/Game'
     4	import './styles.css'
     5	
     6	createRoot(document.getElementById('root')!).render(
     7	  <StrictMode>
     8	    <Game />
     9	  </StrictMode>,
    10	)
===== src/styles.css =====
     1	@import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@500;600;700&display=swap');
     2	
     3	:root {
     4	  color-scheme: dark;
     5	  font-family: 'Rajdhani', system-ui, sans-serif;
     6	  background: #040b17;
     7	  color: #d7f5ff;
     8	  font-synthesis: none;
     9	  text-rendering: geometricPrecision;
    10	}
    11	
    12	* { box-sizing: border-box; }
    13	
    14	html, body, #root { width: 100%; height: 100%; margin: 0; overflow: hidden; }
    15	
    16	button { font: inherit; }
    17	
    18	.game-shell { position: relative; width: 100%; height: 100%; background: #040b17; }
    19	.game-canvas { position: absolute; inset: 0; }
    20	
    21	.hud { position: absolute; inset: 0; pointer-events: none; text-transform: uppercase; letter-spacing: .12em; }
    22	.hud__top { display: flex; justify-content: space-between; align-items: flex-start; padding: 22px 28px; }
    23	.hud__cluster { display: flex; gap: 24px; align-items: flex-start; }
    24	.hud__label { color: #78a4bb; font-size: 11px; line-height: 1; }
    25	.hud__value { margin-top: 4px; color: #e8fbff; font-size: 25px; font-weight: 700; letter-spacing: .08em; }
    26	.hud__value--score { color: #ffe18a; }
    27	
    28	.shield { width: 132px; height: 8px; margin-top: 9px; overflow: hidden; border: 1px solid rgba(140, 218, 241, .55); background: rgba(0, 23, 46, .65); transform: skewX(-18deg); }
    29	.shield__fill { height: 100%; background: linear-gradient(90deg, #ff815e, #ffd36f 45%, #75f4da); box-shadow: 0 0 14px #61e7df; transition: width 120ms linear; }
    30	
    31	.hud__mission { position: absolute; top: 25px; left: 50%; transform: translateX(-50%); text-align: center; }
    32	.hud__mission strong { display: block; color: #a5e8ff; font-size: 13px; }
    33	.hud__mission span { display: block; margin-top: 5px; color: rgba(170, 215, 231, .72); font-size: 10px; }
    34	
    35	.team { position: absolute; right: 28px; bottom: 27px; display: grid; gap: 7px; width: 150px; }
    36	.team__member { display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-left: 2px solid #3c6c83; background: rgba(4, 17, 35, .62); color: #a5ccda; font-size: 11px; }
    37	.team__member--ready { border-color: #6ef0d0; color: #dcfff8; }
    38	.team__member--down { border-color: #ea6b61; color: #ec9b90; opacity: .7; }
    39	.team__role { color: #6c8b9b; font-size: 9px; }
    40	
    41	.status { position: absolute; left: 50%; bottom: 30px; transform: translateX(-50%); color: #c6f5ff; font-size: 13px; text-shadow: 0 0 13px #3ed4ff; }
    42	.status--danger { color: #ff9a81; text-shadow: 0 0 13px #ff4b35; }
    43	
    44	.crosshair { position: absolute; top: 50%; left: 50%; width: 220px; height: 220px; transform: translate(-50%, -50%); border: 1px solid rgba(105, 225, 245, .12); border-radius: 50%; }
    45	.crosshair::before, .crosshair::after { content: ''; position: absolute; background: rgba(125, 236, 255, .32); }
    46	.crosshair::before { top: 50%; left: 17%; width: 66%; height: 1px; }
    47	.crosshair::after { top: 17%; left: 50%; width: 1px; height: 66%; }
    48	
    49	.controls { position: absolute; left: 28px; bottom: 25px; color: rgba(167, 206, 220, .62); font-size: 10px; line-height: 1.7; }
    50	.controls kbd { padding: 1px 4px; border: 1px solid rgba(148, 213, 231, .27); color: #bcf7ff; background: rgba(20, 52, 70, .55); }
    51	
    52	.overlay { position: absolute; inset: 0; display: grid; place-items: center; background: rgba(2, 8, 18, .5); backdrop-filter: blur(6px); pointer-events: auto; }
    53	.overlay__card { width: min(460px, calc(100% - 32px)); padding: 36px; border: 1px solid rgba(133, 224, 248, .45); background: linear-gradient(145deg, rgba(10, 36, 59, .94), rgba(4, 13, 29, .95)); box-shadow: 0 0 70px rgba(36, 167, 218, .2); text-align: center; }
    54	.overlay__eyebrow { color: #69e4ee; font-size: 11px; letter-spacing: .28em; }
    55	.overlay h1 { margin: 9px 0 10px; color: #f1fdff; font-size: clamp(30px, 8vw, 58px); line-height: .95; letter-spacing: .09em; }
    56	.overlay p { margin: 0 auto 24px; max-width: 330px; color: #a3c6d4; font-size: 14px; line-height: 1.4; letter-spacing: .04em; text-transform: none; }
    57	.overlay button { padding: 11px 23px; border: 1px solid #6ce6ed; color: #041521; background: #8af5e4; cursor: pointer; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; }
    58	.overlay button:hover { background: #d7fff7; box-shadow: 0 0 24px rgba(110, 240, 208, .6); }
    59	
    60	@media (max-width: 640px) {
    61	  .hud__top { padding: 14px; }
    62	  .hud__cluster { gap: 12px; }
    63	  .hud__value { font-size: 19px; }
    64	  .hud__mission { top: 15px; }
    65	  .team { right: 14px; bottom: 14px; width: 128px; }
    66	  .controls { left: 14px; bottom: 14px; max-width: 160px; }
    67	  .crosshair { width: 150px; height: 150px; }
    68	}

